// Generated by scripts/sync-workflow.mjs from runner/workflow/liftbay.yml. Do not edit.
export const WORKFLOW_YAML = "# Liftbay builds on your own GitHub Actions minutes.\n# Liftbay starts this workflow; it does nothing on your own pushes or pull requests. With this file on the\n# default branch, Liftbay uses workflow_dispatch. Otherwise (a branch you're trying out), Liftbay points a\n# temporary liftbay/build/<platform>/<build id> branch at your commit, which runs this file from that commit,\n# and deletes it once the build has started.\n# The build gets no repository secrets: the runner exchanges this run's GitHub OIDC token for a\n# one-time Liftbay job token, checked against this repository and this workflow file.\n# Docs: https://github.com/liftbay/runner\nname: Liftbay build\nrun-name: Liftbay build ${{ inputs.build_id || github.ref_name }}\n\non:\n  workflow_dispatch:\n    inputs:\n      build_id:\n        description: Liftbay build id\n        required: true\n        type: string\n      platform:\n        description: Platform\n        required: true\n        type: choice\n        options: [android, ios]\n      api_url:\n        description: Liftbay API\n        required: false\n        type: string\n        default: https://api.liftbay.dev\n  push:\n    branches: [\"liftbay/build/**\"]\n\npermissions:\n  contents: read\n  id-token: write\n\nenv:\n  # Pinned runner release. The archive's SHA-256 is checked before the runner starts.\n  # Release notes and provenance: https://github.com/liftbay/runner/releases/tag/v0.1.3\n  RUNNER_VERSION: \"0.1.3\"\n  RUNNER_SHA256_LINUX_AMD64: \"5c1f9b625664b7faa17c41d761a4186ee1e2918506fb0a43e3da98a2c2c12c71\"\n  RUNNER_SHA256_DARWIN_ARM64: \"4aaffe9c0b059b446198a0054e042fc37fd3e3025609c10c16790f6c01a1a846\"\n\njobs:\n  android:\n    if: inputs.platform == 'android' || startsWith(github.ref_name, 'liftbay/build/android/')\n    runs-on: ubuntu-latest\n    timeout-minutes: 60\n    steps:\n      # GitHub's Linux runners start with about 14 GB free; a React Native release build (NDKs, CMake, four\n      # architectures, Gradle caches) can use more. Remove preinstalled toolchains no app build uses.\n      - name: Free disk space\n        run: |\n          df -h / | tail -1\n          sudo rm -rf /usr/share/dotnet /usr/local/.ghcup /opt/ghc /opt/hostedtoolcache/CodeQL /usr/local/share/boost /usr/share/swift /usr/local/lib/node_modules /usr/local/share/powershell /usr/local/share/chromium /opt/microsoft /opt/google/chrome || true\n          sudo docker image prune --all --force >/dev/null 2>&1 || true\n          df -h / | tail -1\n\n      - uses: actions/checkout@v4\n\n      - uses: actions/setup-java@v4\n        with:\n          distribution: temurin\n          java-version: \"17\"\n\n      - uses: actions/setup-node@v4\n        with:\n          node-version: \"22\"\n\n      - name: Cache JavaScript dependencies\n        uses: actions/cache@v4\n        with:\n          path: |\n            node_modules\n            ~/.npm\n            ~/.cache/yarn\n            ~/.local/share/pnpm/store\n            ~/.bun/install/cache\n          key: js-${{ runner.os }}-${{ hashFiles('package-lock.json', 'yarn.lock', 'pnpm-lock.yaml', 'bun.lock', 'bun.lockb') }}\n          restore-keys: js-${{ runner.os }}-\n\n      - name: Cache Gradle\n        uses: actions/cache@v4\n        with:\n          path: |\n            ~/.gradle/caches\n            ~/.gradle/wrapper\n          key: gradle-${{ runner.os }}-${{ hashFiles('package-lock.json', 'yarn.lock', 'pnpm-lock.yaml', 'bun.lock', 'bun.lockb', 'android/**/*.gradle*', 'android/gradle/wrapper/gradle-wrapper.properties') }}\n          restore-keys: gradle-${{ runner.os }}-\n\n      - name: Install the Liftbay runner\n        env:\n          # Bring your own runner: set the repository variables LIFTBAY_RUNNER_URL (a\n          # liftbay-runner tar.gz you built) and LIFTBAY_RUNNER_SHA256.\n          RUNNER_URL: ${{ vars.LIFTBAY_RUNNER_URL }}\n          RUNNER_SHA256: ${{ vars.LIFTBAY_RUNNER_SHA256 || env.RUNNER_SHA256_LINUX_AMD64 }}\n        run: |\n          set -euo pipefail\n          url=\"${RUNNER_URL:-https://github.com/liftbay/runner/releases/download/v${RUNNER_VERSION}/liftbay-runner_${RUNNER_VERSION}_linux_amd64.tar.gz}\"\n          curl -fsSL --retry 3 -o \"$RUNNER_TEMP/liftbay-runner.tar.gz\" \"$url\"\n          echo \"${RUNNER_SHA256}  $RUNNER_TEMP/liftbay-runner.tar.gz\" | sha256sum -c -\n          tar -xzf \"$RUNNER_TEMP/liftbay-runner.tar.gz\" -C \"$RUNNER_TEMP\" liftbay-runner\n          \"$RUNNER_TEMP/liftbay-runner\" version\n\n      - name: Build\n        env:\n          LIFTBAY_BUILD_ID: ${{ inputs.build_id }}\n          LIFTBAY_API_URL: ${{ inputs.api_url || vars.LIFTBAY_API_URL || 'https://api.liftbay.dev' }}\n        # On a liftbay/build/<platform>/<build id> branch, the build id is the branch name's last part.\n        run: 'LIFTBAY_BUILD_ID=\"${LIFTBAY_BUILD_ID:-${GITHUB_REF_NAME##*/}}\" \"$RUNNER_TEMP/liftbay-runner\" run'\n\n  ios:\n    if: inputs.platform == 'ios' || startsWith(github.ref_name, 'liftbay/build/ios/')\n    runs-on: macos-15\n    timeout-minutes: 90\n    steps:\n      - uses: actions/checkout@v4\n\n      - uses: maxim-lobanov/setup-xcode@v1\n        with:\n          xcode-version: latest-stable\n\n      - uses: actions/setup-node@v4\n        with:\n          node-version: \"22\"\n\n      - name: Cache JavaScript dependencies\n        uses: actions/cache@v4\n        with:\n          path: |\n            node_modules\n            ~/.npm\n            ~/Library/Caches/Yarn\n            ~/Library/pnpm/store\n            ~/.bun/install/cache\n          key: js-${{ runner.os }}-${{ hashFiles('package-lock.json', 'yarn.lock', 'pnpm-lock.yaml', 'bun.lock', 'bun.lockb') }}\n          restore-keys: js-${{ runner.os }}-\n\n      # Only the download caches: a restored ios/Pods would make expo prebuild see a half project.\n      - name: Cache CocoaPods\n        uses: actions/cache@v4\n        with:\n          path: |\n            ~/Library/Caches/CocoaPods\n            ~/.cocoapods\n          key: pods-${{ runner.os }}-${{ hashFiles('ios/Podfile.lock', 'package-lock.json', 'yarn.lock', 'pnpm-lock.yaml', 'bun.lock', 'bun.lockb') }}\n          restore-keys: pods-${{ runner.os }}-\n\n      - name: Install the Liftbay runner\n        env:\n          RUNNER_URL: ${{ vars.LIFTBAY_RUNNER_URL_MACOS }}\n          RUNNER_SHA256: ${{ vars.LIFTBAY_RUNNER_SHA256_MACOS || env.RUNNER_SHA256_DARWIN_ARM64 }}\n        run: |\n          set -euo pipefail\n          url=\"${RUNNER_URL:-https://github.com/liftbay/runner/releases/download/v${RUNNER_VERSION}/liftbay-runner_${RUNNER_VERSION}_darwin_arm64.tar.gz}\"\n          curl -fsSL --retry 3 -o \"$RUNNER_TEMP/liftbay-runner.tar.gz\" \"$url\"\n          echo \"${RUNNER_SHA256}  $RUNNER_TEMP/liftbay-runner.tar.gz\" | shasum -a 256 -c -\n          tar -xzf \"$RUNNER_TEMP/liftbay-runner.tar.gz\" -C \"$RUNNER_TEMP\" liftbay-runner\n          \"$RUNNER_TEMP/liftbay-runner\" version\n\n      - name: Build\n        env:\n          LIFTBAY_BUILD_ID: ${{ inputs.build_id }}\n          LIFTBAY_API_URL: ${{ inputs.api_url || vars.LIFTBAY_API_URL || 'https://api.liftbay.dev' }}\n        # On a liftbay/build/<platform>/<build id> branch, the build id is the branch name's last part.\n        run: 'LIFTBAY_BUILD_ID=\"${LIFTBAY_BUILD_ID:-${GITHUB_REF_NAME##*/}}\" \"$RUNNER_TEMP/liftbay-runner\" run'\n";
